        # Clear the old positions
        for r, c in group:
            if grid[r][c] == val and (r, c) not in processed_min:
                output_grid[r][c] = bg

        # For each group >= 2, fill bounding box
        for comp in new_grouped:
            if not comp:
                continue
            mins = [(r, c) for r in range(comp[0][0], comp[-1][0] + 1) 
                    for c in range(comp[0][1], comp[-1][1] + 1) if (r, c) in comp]
            if len(mins) < 2:
                if (cr, cc) not in processed_min:
                    processed_min.add((cr, cc))
                continue

            # Fill bounding box
            for (gr, gc) in mins:
                if (gr, gc) not in processed_min:
                    output_grid[gr][gc] = val

    return output_grid

